css:
.button {
  background: none;
  border: none;
  padding: 15px 15px;
  border-radius: 10px;
  cursor: pointer;
}

.button:hover {
  background: rgba(170, 170, 170, 0.062);
  transition: 0.5s;
}

.button .svg {
  color: goldenrod;
}
.button:focus > .svg {
  animation: i 0.4s infinite alternate linear;
}
@keyframes i {
  from {
    transform: rotate(-30deg);
  }
  to {
    transform: rotate(30deg);
  }
}
